# guest のテストの共通の部品。呼ばれたコマンドは、スタブが記録のファイルに書く
dns_conf=$(mktemp -d)/dns.conf
calls_log=$(mktemp)
reset_guest() { : >"$calls_log"; rm -f "$dns_conf"; guest_mode=ok; }
guest_state() { guest_mode=$1; }
calls_of() { cat "$calls_log"; }
provision() { PATH="tests/stub-bin:$PATH" CALLS_LOG="$calls_log" GUEST_MODE=$guest_mode DNS_CONF=$dns_conf bash scripts/provision.sh "$1"; }
